 --zy-backdrop:rgba(16,28,41,.55);
 --zy-font:'Noto Serif SC','Source Han Serif SC','SimSun',serif;
 --zy-title:'Ma Shan Zheng','KaiTi','STKaiti',serif;
 --zy-avatar:2rem;
 --zy-avatar-gap:.65rem;
