 --zy-check-shape:polygon(14% 44%,0 65%,50% 100%,100% 16%,80% 0%,43% 62%);
 --zy-check-off:scale(0);
 --zy-check-on:scale(1);
 --zy-check-display:block;
 --zy-background-img:url('https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/dcd59bbb7d6b70618b765994e05ca0c8018cd2e3/assets/%E6%98%BC%E5%A4%9C%E4%B9%8B%E9%97%B4/night-harlequin.png');
 --zy-paper-img:url('https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/eec169101a65a2917eacf8665d1100a8914e01f1/assets/%E6%98%BC%E5%A4%9C%E4%B9%8B%E9%97%B4/paper-flow-v2.png');
 --zy-ribbon-img:url('https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/dcd59bbb7d6b70618b765994e05ca0c8018cd2e3/assets/%E6%98%BC%E5%A4%9C%E4%B9%8B%E9%97%B4/ribbon.png');
