#send_form { background:var(--zy-paper);background-clip:padding-box;border:.8rem  solid transparent;border-image:var(--zy-ribbon-img) 28% fill / 1 / 0 stretch;border-radius:0;padding:.15rem .5rem;color:var(--zy-ink);backdrop-filter:none;box-shadow:none; }
