/* Source: src/windows/mobile.css */
/* 390px独立合同；原生状态控制面板display，不强制打开。 */
@media(max-width:700px) {
 #chat .mes[is_user="true"][is_system="false"] { border-width:.6rem .9rem; padding:.2rem .25rem; }
 #send_form #send_but { width:2.8rem; height:2.9rem; }
 #send_but::before { width:3.4rem; height:3.4rem;right:-.2rem;top:-.5rem; }
 #left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel { min-inline-size:0; max-inline-size:100%; padding:.6rem; border-width:2px; }
 #character_popup, .popup { max-inline-size:calc(100% - 1rem); padding:.65rem; }
 #user-settings-block #user-settings-block-content { gap:.6rem; }
 #completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt { grid-template-columns:minmax(0,1fr) 4.5rem 2.3rem; gap:.25rem; }
 #completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name { white-space:normal; overflow-wrap:anywhere; }
 #completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .prompt_manager_prompt_controls span { width:1.15rem; }
}


